// ============================================================
// poems_hd.js
// 高细节月球纹理生成器：不再需要单独的 moon_texture_realistic.png
// 兼容现有 index：继续提供 window.createProceduralMoonTexture(size)
// 内部嵌入高细节月面数据，页面启动时一次性还原成 Canvas。
// ============================================================
(function () {
  "use strict";

  const MOON_W = 512;
  const MOON_H = 512;

  // 由原高细节月球纹理缩放后嵌入的 RGBA 数据。
  const MOON_RGBA_B64 =
``;

  let cachedBaseCanvas = null;

  function buildBaseCanvas() {
    if (cachedBaseCanvas) return cachedBaseCanvas;

    const binary = atob(MOON_RGBA_B64);
    const bytes = new Uint8ClampedArray(binary.length);

    // 分块转换，避免一次循环造成明显卡顿。
    const CHUNK = 65536;
    for (let start = 0; start < binary.length; start += CHUNK) {
      const end = Math.min(binary.length, start + CHUNK);
      for (let i = start; i < end; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
    }

    const c = document.createElement("canvas");
    c.width = MOON_W;
    c.height = MOON_H;
    const ctx = c.getContext("2d", { alpha: true });
    const imgData = new ImageData(bytes, MOON_W, MOON_H);
    ctx.putImageData(imgData, 0, 0);

    cachedBaseCanvas = c;
    return c;
  }

  window.createProceduralMoonTexture = function createProceduralMoonTexture(size = 768) {
    const source = buildBaseCanvas();

    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;

    const ctx = canvas.getContext("2d", { alpha: true });
    ctx.clearRect(0, 0, size, size);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";

    // 主月面
    ctx.drawImage(source, 0, 0, size, size);

    // 很轻的球体明暗增强：保留原图细节，同时让立体感更强
    const cx = size * 0.5;
    const cy = size * 0.5;
    const r = size * 0.47;

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.clip();

    // 左上柔光
    const light = ctx.createRadialGradient(
      cx - r * 0.30, cy - r * 0.34, 0,
      cx - r * 0.16, cy - r * 0.18, r * 0.88
    );
    light.addColorStop(0, "rgba(255,252,242,0.10)");
    light.addColorStop(0.42, "rgba(255,245,220,0.035)");
    light.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = light;
    ctx.fillRect(0, 0, size, size);

    // 球缘压暗
    const limb = ctx.createRadialGradient(cx, cy, r * 0.64, cx, cy, r);
    limb.addColorStop(0, "rgba(0,0,0,0)");
    limb.addColorStop(0.82, "rgba(12,14,18,0.025)");
    limb.addColorStop(1, "rgba(5,7,12,0.17)");
    ctx.fillStyle = limb;
    ctx.fillRect(0, 0, size, size);

    // 右下极轻冷色反光
    const cool = ctx.createLinearGradient(
      cx - r * 0.2, cy - r * 0.3,
      cx + r, cy + r
    );
    cool.addColorStop(0, "rgba(0,0,0,0)");
    cool.addColorStop(1, "rgba(90,115,155,0.035)");
    ctx.fillStyle = cool;
    ctx.fillRect(0, 0, size, size);

    ctx.restore();

    return canvas;
  };
})();
